class Solution:
    def missingRanges(self, nums, lower, upper):
        present = [False] * (upper - lower + 1)
        for x in nums:
            if lower <= x <= upper:
                present[x - lower] = True
        res = []
        start = None
        for i in range(upper - lower + 1):
            if not present[i]:
                if start is None:
                    start = i
            elif start is not None:
                res.append([start + lower, i - 1 + lower])
                start = None
        if start is not None:
            res.append([start + lower, upper])
        return res

