class Solution {
public:
    vector<vector<int>> missingRanges(vector<int>& nums, int lower, int upper) {
        int m = upper - lower + 1;
        vector<char> present(m, 0);
        for (int x : nums)
            if (x >= lower && x <= upper) present[x - lower] = 1;
        vector<vector<int>> res;
        int start = -1;
        for (int i = 0; i < m; i++) {
            if (!present[i]) {
                if (start == -1) start = i;
            } else if (start != -1) {
                res.push_back({start + lower, i - 1 + lower});
                start = -1;
            }
        }
        if (start != -1) res.push_back({start + lower, upper});
        return res;
    }
};

