class Solution {
    public int[][] missingRanges(int[] nums, int lower, int upper) {
        int m = upper - lower + 1;
        boolean[] present = new boolean[m];
        for (int x : nums)
            if (x >= lower && x <= upper) present[x - lower] = true;
        java.util.List<int[]> res = new java.util.ArrayList<>();
        int start = -1;
        for (int i = 0; i < m; i++) {
            if (!present[i]) {
                if (start == -1) start = i;
            } else if (start != -1) {
                res.add(new int[]{start + lower, i - 1 + lower});
                start = -1;
            }
        }
        if (start != -1) res.add(new int[]{start + lower, upper});
        return res.toArray(new int[0][]);
    }
}

