var missingRanges = function(nums, lower, upper) {
    const m = upper - lower + 1;
    const present = new Array(m).fill(false);
    for (const x of nums)
        if (x >= lower && x <= upper) present[x - lower] = true;
    const res = [];
    let start = -1;
    for (let i = 0; i < m; i++) {
        if (!present[i]) {
            if (start === -1) start = i;
        } else if (start !== -1) {
            res.push([start + lower, i - 1 + lower]);
            start = -1;
        }
    }
    if (start !== -1) res.push([start + lower, upper]);
    return res;
};

