class Solution:
    def missingRanges(self, nums, lower, upper):
        vals = sorted(set(x for x in nums if lower <= x <= upper))
        res = []
        cur = lower
        for v in vals:
            if v > cur:
                res.append([cur, v - 1])
            cur = v + 1
        if cur <= upper:
            res.append([cur, upper])
        return res

