class Solution {
public:
    vector<vector<int>> missingRanges(vector<int>& nums, int lower, int upper) {
        vector<int> vals;
        for (int x : nums)
            if (x >= lower && x <= upper) vals.push_back(x);
        sort(vals.begin(), vals.end());
        vals.erase(unique(vals.begin(), vals.end()), vals.end());
        vector<vector<int>> res;
        long long cur = lower;
        for (int v : vals) {
            if (v > cur) res.push_back({(int)cur, v - 1});
            cur = (long long)v + 1;
        }
        if (cur <= upper) res.push_back({(int)cur, upper});
        return res;
    }
};

