class Solution {
    public int[][] missingRanges(int[] nums, int lower, int upper) {
        java.util.TreeSet<Integer> set = new java.util.TreeSet<>();
        for (int x : nums)
            if (x >= lower && x <= upper) set.add(x);
        java.util.List<int[]> res = new java.util.ArrayList<>();
        long cur = lower;
        for (int v : set) {
            if (v > cur) res.add(new int[]{(int) cur, v - 1});
            cur = (long) v + 1;
        }
        if (cur <= upper) res.add(new int[]{(int) cur, upper});
        return res.toArray(new int[0][]);
    }
}

